package com.aryaa.sdm.controller;
import com.aryaa.sdm.dto.*; import com.aryaa.sdm.service.RegionService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/regions") public class RegionController{private final RegionService service;public RegionController(RegionService s){service=s;}@GetMapping public List<RegionDto> getAllRegions(){return service.getAllRegions();}@PostMapping("/{name}/alert") public AlertResponse alertRegion(@PathVariable String name){return service.alertRegion(name);}@PostMapping("/{name}/resolve") public RegionDto resolveRegion(@PathVariable String name){return service.resolveRegion(name);}}
